(700,1492,'Incontinence of feces not due to organic defect or illness.','en',2,'2026-10-08 22:40:23',NULL,NULL,'12856FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(701,1494,'Disorders of increased melanin pigmentation that develop without preceding inflammatory disease.','en',2,'2026-10-08 22:40:23',NULL,NULL,'12810FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
