(733,1568,'Sensation of discomfort, distress, or agony in the abdominal region.','en',2,'2026-10-08 22:40:24',NULL,NULL,'12338FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(734,1569,'Disorders in which anxiety (persistent feelings of apprehension, tension, or uneasiness) is the predominant disturbance.','en',2,'2026-10-08 22:40:24',NULL,NULL,'12337FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
