(753,1593,'Varicosities of the hemorrhoidal venous plexuses.','en',2,'2026-10-08 22:40:25',NULL,NULL,'12058FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(754,1594,'Hemorrhage within the pleural cavity.','en',2,'2026-10-08 22:40:25',NULL,NULL,'12056FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(755,1597,'Small, hard, pathological concretions, composed chiefly of cholesterol, calcium salts, and bile pigments, formed in the gallbladder or in a bile duct.','en',2,'2026-10-08 22:40:25',NULL,NULL,'7FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
