(1323,2842,'Fractures of the larger bone of the forearm.','en',2,'2026-10-08 22:40:40',NULL,NULL,'5275FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1324,2845,'Fracture of the lower end of the radius in which the lower fragment is displaced posteriorly.','en',2,'2026-10-08 22:40:40',NULL,NULL,'5270FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
(1325,2850,'Fractures in which the break in bone is not accompanied by an external wound.','en',2,'2026-10-08 22:40:40',NULL,NULL,'5266FFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFF'),
