INSERT INTO `global_property` VALUES
('@openmrs/esm-fast-data-entry-app.groupSessionVisitTypeUuid','78370d15-38ad-48a1-825f-f0e9ff60d5a1','UUID of the visit type used by Fast Data Entry to create visits when in \'group sessions\' entry workflow','f785faff-4c55-485c-b6a7-dcf6d1d66558',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.addressToEntryMapUpdaterLastStartTime',NULL,'The module uses this field to store when the AddressToEntryMapUpdater task was last started; DO NOT MODIFY','f9181696-2c4b-4577-ad27-c46b58105b32',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.allowFreetext','true','Valid values: true/false. When overriding the address portlet, allow the entry of free text for address fields associated with the address hierarchy by providing an \"Other\" option','76f134c6-d0bb-4e20-bbd0-717765394ff2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.enableOverrideOfAddressPortlet','true','Valid values: true/false. When enabled, the existing \"edit\" component of the address portlet is overridden by the new functionality provided by the address hierarchy module','1c1287be-fe06-4518-9feb-51a72918e09c',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.initializeAddressHierarchyCacheOnStartup','true','Sets whether to initialize the address hierarchy in-memory cache (which is used to speed up address hierarchy searches.\nGenerally, you want to set this to \"true\", though developers may want to set it to false during development\nto speed module start-up.','a5543e07-fa7c-4e30-84df-034fa00fd7d2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.mandatory','false','true/false whether or not the addresshierarchy module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','7add3e24-208b-4c50-9288-e5c200bda186',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.soundexProcessor',NULL,'If the Name Phonetics module is installed, this defines the name of a soundex algorithm used by the getPossibleFullAddresses service method.','55d493f7-6b1f-4321-9a9c-6d33ffb2775b',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('addresshierarchy.started','true','DO NOT MODIFY. true/false whether or not the addresshierarchy module has been started.  This is used to make sure modules that were running  prior to a restart are started again','b15634ef-2662-4e90-9a79-19e5a1a7a1c3',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.allergen.ConceptClasses','Drug,MedSet','A comma-separated list of the allowed concept classes for the allergen field of the allergy dialog','eaf3f161-3752-412e-9a88-7bba5b702345',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.allergen.drug','162552AAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the drug allergens concept','73901ac7-58af-4af7-ba24-84d4fa6cc5b9',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
