('allergy.concept.severity.severe','1500AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the SEVERE severity concept','4fa87d11-8875-49d1-87d2-2750397670af',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.concept.unknown','1067AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA','UUID for the allergy unknown concept','7e0827a8-d31b-4977-9b9a-fd8c2e2725f2',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('allergy.reaction.ConceptClasses','Symptom','A comma-separated list of the allowed concept classes for the reaction field of the allergy dialog','5362e179-b305-4f3d-a689-1171cfcd5cbc',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('application.name','OpenMRS','The name of this application, as presented to the user, for example on the login and welcome pages.','e7681fbd-f513-40a2-bfdc-0c81c43842f4',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('appointments.mandatory','false','true/false whether or not the appointments module MUST start when openmrs starts.  This is used to make sure that mission critical modules are always running if openmrs is running.','fbc8f5c8-54a1-4a78-853d-5fce0d27b2e8',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('appointments.started','true','DO NOT MODIFY. true/false whether or not the appointments module has been started.  This is used to make sure modules that were running  prior to a restart are started again','2fa3589a-e1b1-43cd-a566-1f19e805a088',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForAppointments','/openmrs/ws/rest/v1/appointments/{uuid}','URL pattern to use for published appointment events. Default is /openmrs/ws/rest/v1/appointments/{uuid}. If you change default value, please add your custom implementation for the given URL','0e2df205-c369-11f1-950a-0242ac150002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForAppointmentService','/openmrs/ws/rest/v1/appointment-services/{uuid}','URL pattern to use for published appointment service events. Default is /openmrs/ws/rest/v1/appointment-services/{uuid}. If you change default value, please add your custom implementation for the given URL','0e2d2753-c369-11f1-950a-0242ac150002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForBedTagMap','/openmrs/ws/rest/v1/bedTagMap/{uuid}','URL pattern to use for published bed tag map events. Default is /openmrs/ws/rest/v1/bedTagMap/{uuid}. If you change default value, please add your custom implementation for the given URL.','0b85ad23-c369-11f1-950a-0242ac150002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.event.urlPatternForRecurringAppointments','/openmrs/ws/rest/v1/recurring-appointments?uuid={uuid}','URL pattern to use for published Recurring appointment events. Default is /openmrs/ws/rest/v1/recurring-appointments?uuid={uuid}. If you change default value, please add your custom implementation for the given URL','0e35ca5c-c369-11f1-950a-0242ac150002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForAppointments','true','If set true, events related to appointment changes are published','0e2d9e8e-c369-11f1-950a-0242ac150002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForAppointmentService','true','If set true, events related to appointment service changes are published','0e2ccd2f-c369-11f1-950a-0242ac150002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('atomfeed.publish.eventsForBedTagMapChange','true','If set true, events related to bed tag map changes are published','0b85165e-c369-11f1-950a-0242ac150002',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.allowedFileExtensions','jpeg,jpg,png,pdf','Comma-separated list of case-insensitive file extensions that are allowed to be uploaded.','b51c7175-bb56-489f-ab26-0a0398f57f7d',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.allowNoCaption','false','Set this property to \'true\' to allow empty attachments\ncaptions','983bfd3d-60e0-41e0-9512-844d3c9ccd67',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.allowWebcam','true','Set this property to \'true\' to allow the use of the\nwebcam for file\nuploads','1fee1af3-7881-40cb-884f-57572d67ae59',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.associateWithVisit','true','If set false, then when uploading an attachment via the \"Attachments Controller\", the visit context will\n*not* be included (and therefore the attachment will not be associated with that visit)','8e0cdf75-fc0b-4802-92cb-b6f8193f552b',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
('attachments.conceptComplexUuidList','[\"7cac8397-53cd-4f00-a6fe-028e8d743f8e\",\"42ed45fd-f3f6-44b6-bfc2-8bde1bb41e00\"]','List of concept complex UUIDs that are used in queries\nfor viewing\ndocuments','a08a8b18-f229-4850-9aab-feb3de148138',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),
